#!/usr/bin/env node
// Dangling-reference gate.
//
// Prose and code comments cite repo paths constantly ("see docs/X.md",
// "generated by scripts/Y.mjs"). Nothing type-checks those citations, so when
// the target is deleted or moved the reference rots silently and an agent
// reading the file is sent to a file that does not exist. The T2 prose census
// found 8 such rotted citations at once — three pointing INTO .gitignore'd
// directories (broken for anyone who clones the repo), one of them a
// user-facing `fabric doctor` remediation string.
//
// Only two citation forms are checked, because only these two are decidable
// without guessing. A first cut that flagged every path-shaped string produced
// 1445 hits, nearly all of them prose ("React/Next.js") or example paths in
// vendored skill data — a gate that noisy is a gate nobody keeps green:
//
//   1. Markdown link targets — `[text](target)`. A link target IS a path by
//      definition, so relative forms are unambiguous here.
//   2. Paths anchored on a real top-level entry of THIS repo (packages/,
//      scripts/, docs/, .workflow/, ...). The anchor set is read off disk, so
//      generic example paths from other projects cannot match.

import { execFileSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { dirname, join, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");

// Files whose path citations are NOT expected to resolve.
const SKIP_SOURCE = [
  // Historical ledgers: entries describe the repo as it was at the time they
  // were written. A closed issue naming a since-deleted file is a correct
  // record, not a rotted citation.
  "CHANGELOG.md",
  ".workflow/issues/",
  ".workflow/harvest/",
  ".workflow/state.json",
  ".workflow/worktree-scope.json",
  ".workflow/worktrees.json",
  // This file: its ALLOWLIST is by definition a list of paths that do not
  // resolve, so scanning itself is guaranteed self-contradiction. (Caught only
  // after `git add` — while untracked it was invisible to `git ls-files`, so
  // the gate silently skipped itself on every pre-commit run.)
  "scripts/lint-dangling-refs.mjs",
  // Pattern files — the "paths" are globs to match, not files to visit.
  ".gitignore",
  ".gitattributes",
  ".maestroignore",
  ".npmignore",
  // Task tracker, not shipped; carries its own churning path references.
  ".trellis/",
  // Installed client subtrees — generated copies of packages/cli/templates/**
  // (checked at the template) plus vendored third-party skills we do not own.
  ".claude/skills/",
  ".claude/hooks/",
  ".codex/",
  // Tests legitimately construct synthetic paths (".workflow/a/b.md") as
  // fixture input; those are arguments, not citations.
  "__tests__/",
  ".test.ts",
  ".test.mts",
];

// Cited paths that are intentionally unresolvable. Keep each entry justified —
// an unexplained allowlist entry is how this gate rots.
//
// Keys are `<source file>::<citation>`. Scoping to the citing file matters:
// `packages/cli/src/commands/hooks.ts` is a made-up path in a skill worked
// example AND was a real, since-deleted file cited by live code. A bare-path
// allowlist would suppress the second along with the first.
const ALLOWLIST = new Map([
  // Worked examples in skill ref docs teach the SHAPE of a call; their paths
  // are deliberately illustrative and must not track real files.
  ["packages/cli/templates/skills/fabric-archive/ref/phase-3-review.md::packages/cli/src/commands/plan.ts", "worked example"],
  ["packages/cli/templates/skills/fabric-archive/ref/phase-3-review.md::packages/server/src/foo.ts", "worked example"],
  ["packages/cli/templates/skills/fabric-archive/ref/phase-3-review.md::packages/server/src/services/extract.ts", "worked example"],
  ["packages/cli/templates/skills/fabric-archive/ref/phase-3-review.md::packages/server/src/services/promote.ts", "worked example"],
  // A hypothetical 3-engineer project's architecture doc ("Why a monolith?"),
  // used to teach that a doc-mined observation must NOT inherit the miner file's
  // path as relevance_paths. Deliberately NOT this repo's docs/ARCHITECTURE.md —
  // renaming it to match would bind an illustrative example to a real file and
  // make the example read as a citation of our own architecture.
  ["packages/cli/templates/skills/fabric-archive/ref/source-mode.md::docs/architecture.md", "worked example"],
  ["packages/cli/templates/skills/fabric-archive/ref/source-mode.md::packages/server/src/retry.ts", "worked example"],
  ["packages/cli/templates/skills/fabric-archive/ref/source-mode.md::packages/server/src/lib/retry.ts", "worked example"],
  ["packages/cli/templates/skills/fabric-archive/ref/worked-examples.md::packages/cli/src/commands/hooks.ts", "worked example"],
  ["packages/cli/templates/skills/fabric-review/ref/modify-flow.md::packages/server/src/lib/retry.ts", "worked example"],
  ["packages/server/src/services/__testing__/doctor-test-helpers.ts::packages/server/rules.contract.test.ts", "fixture path written by the helper into a temp project, not a repo file"],
]);

// Anchors for form 2: top-level directories that hold SOURCE-CONTROLLED files
// only. Read off disk (rather than hardcoded) so example paths from other
// projects cannot match, then intersected with this allow-set.
//
// Runtime dirs (.fabric/, .workflow/, .claude/, .codex/) are deliberately NOT
// anchors: paths under them are overwhelmingly artifacts created in a USER's
// project at runtime (`.fabric/agents.meta.json`, `.fabric/.import-state.json`,
// `.fabric/project-rules.md`), which correctly do not exist in this repo.
// Anchoring on them produced ~90 unfixable hits — noise that would train
// everyone to ignore the gate.
const SOURCE_ANCHORS = ["packages", "scripts", "docs", ".github"];
const TOP_LEVEL = new Set(
  readdirSync(ROOT, { withFileTypes: true })
    .filter((e) => e.isDirectory() && SOURCE_ANCHORS.includes(e.name))
    .map((e) => e.name),
);

const EXTENSIONS = ["md", "ts", "mts", "cts", "tsx", "js", "mjs", "cjs", "json", "jsonl", "yml", "yaml", "sh"];
const EXT_GROUP = EXTENSIONS.join("|");

// Form 2: anchored on a real top-level dir, ending in a known extension.
const ANCHORED_RE = new RegExp(
  String.raw`(?<![\w./-])((?:[\w.-]+)(?:/[\w.-]+)+\.(?:${EXT_GROUP}))\b`,
  "g",
);

// Form 1: markdown link target. Excludes URLs and pure anchors.
const MD_LINK_RE = /\]\(([^)\s#]+)(?:\s+"[^"]*")?\)/g;

function trackedFiles() {
  return execFileSync("git", ["ls-files", "-z"], { cwd: ROOT, maxBuffer: 1e9 })
    .toString()
    .split("\0")
    .filter(Boolean);
}

const isSkippedSource = (file) => SKIP_SOURCE.some((marker) => file === marker || file.includes(marker));

// existsSync is NOT enough on macOS: the default APFS volume is case-INsensitive,
// so `docs/architecture.md` "exists" locally while Linux CI (ext4, case-sensitive)
// correctly reports it dangling. That divergence makes the gate pass on every dev
// machine and fail only after push — the worst possible place to learn it.
// So verify each segment against the real directory listing.
const dirCache = new Map();
function existsCaseSensitive(abs) {
  if (!existsSync(abs)) return false;
  const rel = relative(ROOT, abs);
  if (rel.startsWith("..") || rel === "") return true; // outside the repo: no listing to check against
  let dir = ROOT;
  for (const segment of rel.split(sep)) {
    let names = dirCache.get(dir);
    if (!names) {
      try {
        names = new Set(readdirSync(dir));
      } catch {
        return false;
      }
      dirCache.set(dir, names);
    }
    if (!names.has(segment)) return false;
    dir = join(dir, segment);
  }
  return true;
}

// Resolve the way a reader would: a relative citation is relative to the citing
// file (that is what a markdown link means), otherwise relative to the root.
function resolves(citation, sourceFile) {
  if (citation.startsWith("./") || citation.startsWith("../")) {
    return existsCaseSensitive(resolve(ROOT, dirname(sourceFile), citation));
  }
  return (
    existsCaseSensitive(join(ROOT, citation)) ||
    existsCaseSensitive(resolve(ROOT, dirname(sourceFile), citation))
  );
}

function citations(file, line) {
  const found = new Set();

  if (file.endsWith(".md")) {
    for (const m of line.matchAll(MD_LINK_RE)) {
      const target = m[1];
      if (/^[a-z][a-z0-9+.-]*:/i.test(target)) continue; // http:, mailto:, ...
      found.add(target);
    }
  }

  for (const m of line.matchAll(ANCHORED_RE)) {
    if (TOP_LEVEL.has(m[1].split("/")[0])) found.add(m[1]);
  }

  return found;
}

function main() {
  const violations = [];
  let scanned = 0;

  for (const file of trackedFiles()) {
    if (isSkippedSource(file)) continue;

    const abs = join(ROOT, file);
    let source;
    try {
      if (statSync(abs).size > 2_000_000) continue;
      source = readFileSync(abs, "utf8");
    } catch {
      continue; // binary or unreadable — nothing to cite
    }
    scanned += 1;

    for (const [index, line] of source.split("\n").entries()) {
      for (const citation of citations(file, line)) {
        if (ALLOWLIST.has(`${file}::${citation}`)) continue;
        if (resolves(citation, file)) continue;
        violations.push({ file, line: index + 1, citation });
      }
    }
  }

  if (violations.length === 0) {
    process.stdout.write(`[lint-dangling-refs] PASS — ${scanned} tracked files scanned, 0 dangling path citations.\n`);
    return;
  }

  process.stderr.write(`[lint-dangling-refs] FAIL — ${violations.length} dangling path citation(s):\n`);
  for (const v of violations) {
    process.stderr.write(`  ${v.file}:${v.line}  ->  ${v.citation}\n`);
  }
  process.stderr.write(
    "\nFix the citation, restore the target, or add it to ALLOWLIST in scripts/lint-dangling-refs.mjs with a reason.\n",
  );
  process.exitCode = 1;
}

main();
